// Arduino Sketch


#include <SoftwareSerial.h>

// Настраиваем Bluetooth на пинах 2 (RX) и 3 (TX)
SoftwareSerial mySerial(2, 3); 

int led1 = 4;
int led2 = 5;
int led3 = 6;

void setup() {
  pinMode(led1, OUTPUT);
  pinMode(led2, OUTPUT);
  pinMode(led3, OUTPUT);

  mySerial.begin(9600); // Запускаем связь с Bluetooth
}

void loop() {
  if (mySerial.available()) {
    String command = mySerial.readStringUntil('\n'); // Читаем команду с телефона
    command.trim(); // Очищаем от лишних пробелов

    if (command == "on") {
      // Включить всё!
      digitalWrite(led1, HIGH);
      digitalWrite(led2, HIGH);
      digitalWrite(led3, HIGH);
    } 
    else if (command == "off") {
      // Выключить всё
      digitalWrite(led1, LOW);
      digitalWrite(led2, LOW);
      digitalWrite(led3, LOW);
    } 
    else if (command == "police") {
      // Спецэффект: мигалка полиции на 5 секунд!
      for(int i = 0; i < 10; i++) {
        digitalWrite(led1, HIGH);   digitalWrite(led2, LOW);
        delay(250);
        digitalWrite(led1, LOW);    digitalWrite(led2, HIGH);
        delay(250);
      }
      digitalWrite(led2, LOW);
    }
    else if (command == "blink") {
      // Все дружно моргают
      digitalWrite(led1, HIGH); digitalWrite(led2, HIGH); digitalWrite(led3, HIGH);
      delay(500);
      digitalWrite(led1, LOW);  digitalWrite(led2, LOW);  digitalWrite(led3, LOW);
    }
  }
}
